<?php
declare(strict_types=1);namespace Vendi\Sales;use PDO;use RuntimeException;
final class VoidSaleService{public function __construct(private PDO $db,private RefundService $refunds){}
 public function void(int$b,int$branch,int$u,int$saleId,string$reason):void{if(trim($reason)==='')throw new RuntimeException('El motivo es obligatorio.');$this->db->beginTransaction();try{$q=$this->db->prepare("SELECT status FROM sales WHERE id=? AND business_id=? AND branch_id=? FOR UPDATE");$q->execute([$saleId,$b,$branch]);$status=$q->fetchColumn();if($status!=='completed')throw new RuntimeException('La venta no puede cancelarse.');$r=$this->db->prepare("SELECT COUNT(*) FROM refunds WHERE sale_id=? AND status='completed'");$r->execute([$saleId]);if((int)$r->fetchColumn()>0)throw new RuntimeException('Una venta con devoluciones previas no puede cancelarse completa; devuelve únicamente las partidas restantes.');$items=$this->db->prepare("SELECT id sale_item_id,qty FROM sale_items WHERE sale_id=?");$items->execute([$saleId]);$lines=$items->fetchAll();if(!$lines)throw new RuntimeException('Venta sin partidas.');$this->db->commit();$this->refunds->refund($b,$branch,$u,$saleId,$lines,'Cancelación: '.trim($reason),[]);$this->db->beginTransaction();$this->db->prepare("UPDATE sales SET status='cancelled' WHERE id=? AND status='refunded'")->execute([$saleId]);$this->db->prepare("INSERT INTO sale_voids(business_id,branch_id,sale_id,user_id,reason) VALUES(?,?,?,?,?)")->execute([$b,$branch,$saleId,$u,trim($reason)]);$this->db->prepare("INSERT INTO audit_log(business_id,branch_id,user_id,event,entity_type,entity_id,metadata,created_at) VALUES(?,?,?,'sale.voided','sale',?,?,NOW())")->execute([$b,$branch,$u,$saleId,json_encode(['reason'=>trim($reason)],JSON_UNESCAPED_UNICODE)]);$this->db->commit();}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
}